let L=(navigator.language||'pl').toLowerCase().startsWith('pl')?'pl':'en';
function applyLang(){document.documentElement.lang=L;$('#lang').value=L;for(const el of $$('[data-i]'))if(T[L][el.dataset.i])el.textContent=T[L][el.dataset.i];
  $('#cprSteps').innerHTML=T[L].cpr.map(s=>`<li>${esc(s)}</li>`).join('');$('#aedSteps').innerHTML=T[L].aed.map(s=>`<li>${esc(s)}</li>`).join('');
  $('#cprSrc').innerHTML=`${esc(T[L].src)} <a href="https://www.prc.krakow.pl/wp-content/uploads/2025/12/BLS_Algorytmy.pdf">PRR – BLS 2025 (PDF)</a>`;renderSos()}
$('#lang').onchange=e=>{L=e.target.value;try{localStorage.setItem('pz_lang',L)}catch{}applyLang()};
